// LoadingContext.tsx
import { createContext, useContext, useState, ReactNode } from 'react';

interface LoadingContextType {
  loadingCount: number;
  startLoading: () => void;
  stopLoading: () => void;
}

const LoadingContext = createContext<LoadingContextType | undefined>(undefined);

export const LoadingProvider = ({ children }: { children: ReactNode }) => {
  const [loadingCount, setLoadingCount] = useState(0);
  const startLoading = () => setLoadingCount(c => c + 1);
  const stopLoading = () => setLoadingCount(c => Math.max(0, c - 1));
  return (
    <LoadingContext.Provider value={{ loadingCount, startLoading, stopLoading }}>
      {children}
    </LoadingContext.Provider>
  );
};

export const useLoading = () => {
  const ctx = useContext(LoadingContext);
  if (!ctx) throw new Error('useLoading must be used within LoadingProvider');
  return { isLoading: ctx.loadingCount > 0, ...ctx };
};

// requestWrapper.ts
export async function withLoading<T>(promise: Promise<T>): Promise<T> {
  const { startLoading, stopLoading } = useLoading(); // note: call inside a component or provide a non‑hook version
  startLoading();
  try {
    return await promise;
  } finally {
    stopLoading();
  }
}
