// Store.java
public final class Store<T> {
    private final ObjectProperty<T> state;
    private final List<Middleware<T>> middlewares = new CopyOnWriteArrayList<>();
    private final List<StateChangeListener<T>> subscribers = new CopyOnWriteArrayList<>();
    private final Deque<T> history = new ArrayDeque<>();
    private static final int MAX_HISTORY = 50;

    public Store(T initialState) {
        this.state = new SimpleObjectProperty<>(initialState);
        history.add(initialState);
    }

    public T getState() { return state.get(); }
    public ObjectProperty<T> stateProperty() { return state; }

    public void dispatch(Action action) {
        T newState = reduce(getState(), action);
        if (newState != getState()) {
            history.addLast(newState);
            if (history.size() > MAX_HISTORY) history.removeFirst();
            state.set(newState);
            subscribers.forEach(l -> l.onChange(getState(), newState));
        }
        middlewares.forEach(m -> m.process(action, this));
    }

    public void addMiddleware(Middleware<T> m) { middlewares.add(m); }
    public void subscribe(StateChangeListener<T> l) { subscribers.add(l); }
    public void timeTravel(int stepsBack) {
        if (stepsBack > 0 && stepsBack < history.size()) {
            T target = new ArrayList<>(history).get(history.size() - 1 - stepsBack);
            state.set(target);
        }
    }

    protected T reduce(T current, Action action) { return current; }
}

// Action.java
public sealed interface Action permits Increment, SetUser, FetchMetrics {}
record Increment(int amount) implements Action {}
record SetUser(User user) implements Action {}
record FetchMetrics() implements Action {}

// Middleware.java
@FunctionalInterface
public interface Middleware<T> {
    void process(Action action, Store<T> store);
}
