public final class DashboardStore extends Store<DashboardState> {
    public DashboardStore() {
        super(new DashboardState(null, List.of(), Map.of()));
        addMiddleware(this::handleAsync);
    }

    @Override
    protected DashboardState reduce(DashboardState current, Action action) {
        return switch (action) {
            case SetUser a -> current.withUser(a.user());
            case Increment a -> current.withMetrics(current.metrics() + a.amount());
            default -> current;
        };
    }

    private void handleAsync(Action action, Store<DashboardState> store) {
        if (action instanceof FetchMetrics) {
            CompletableFuture.supplyAsync(this::fetchFromApi)
                .thenAccept(data -> store.dispatch(new SetMetrics(data)));
        }
    }
}
